93. public class AppConfig
94. {
95.     private readonly Dictionary<string, string> _values = new();
96. 
97.     public void Set(string key, string value) => _values[ValidateKey(key)] = value;
98.     public string? Get(string key) => _values.GetValueOrDefault(key);
99. 
100.     public string Serialize() =>
101.         System.Text.Json.JsonSerializer.Serialize(_values);
102. 
103.     public static AppConfig Deserialize(string json)
104.     {
105.         var config = new AppConfig();
106.         var dict = System.Text.Json.JsonSerializer.Deserialize<Dictionary<string, string>>(json)!;
107.         foreach (var kv in dict)
108.             config.Set(kv.Key, kv.Value);
109.         return config;
110.     }
111. 
112.     public string FormatConnectionString() =>
113.         $"Host={Get("Host")};Port={Get("Port")};Database={Get("Database")}";
114. 
115.     public static AppConfig ParseConnectionString(string connStr)
116.     {
117.         var config = new AppConfig();
118.         foreach (var part in connStr.Split(';'))
119.         {
120.             var kv = part.Split('=', 2);
121.             if (kv.Length == 2) config.Set(kv[0], kv[1]);
122.         }
123.         return config;
124.     }
125. 
126.     public static string ValidateKey(string key)
127.     {
128.         if (string.IsNullOrWhiteSpace(key))
129.             throw new ArgumentException("Key cannot be empty", nameof(key));
130.         if (key.Contains(' '))
131.             throw new ArgumentException("Key cannot contain spaces", nameof(key));
132.         return key;
133.     }
134. 
135.     public AppConfig Clone()
136.     {
137.         var clone = new AppConfig();
138.         foreach (var kv in _values)
139.             clone.Set(kv.Key, kv.Value);
140.         return clone;
141.     }
142. 
143.     public string ToDisplayString() =>
144.         string.Join(", ", _values.Select(kv => $"{kv.Key}={kv.Value}"));
145. }
