{"file_text":"using Microsoft.VisualStudio.TestTools.UnitTesting;
using Warehouse;

namespace InventoryTracker.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private Warehouse.InventoryTracker _tracker = null!;

    [TestInitialize]
    public void SetUp() => _tracker = new Warehouse.InventoryTracker();

    // -------------------------------------------------------------------------
    // GetStockLevel
    // -------------------------------------------------------------------------

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        int level = _tracker.GetStockLevel("SKU-UNKNOWN");

        Assert.AreEqual(0, level);
    }

    [TestMethod]
    public void GetStockLevel_AfterAddStock_ReturnsAddedQuantity()
    {
        _tracker.AddStock("SKU-A", 50);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void GetStockLevel_AfterMultipleAddStock_ReturnsCumulativeTotal()
    {
        _tracker.AddStock("SKU-B", 30);
        _tracker.AddStock("SKU-B", 20);

        Assert.AreEqual(50, _tracker.GetStockLevel("SKU-B"));
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void GetStockLevel_NullSku_ThrowsArgumentNullException()
    {
        _tracker.GetStockLevel(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GetStockLevel_EmptySku_ThrowsArgumentException()
    {
        _tracker.GetStockLevel(string.Empty);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void GetStockLevel_WhitespaceSku_ThrowsArgumentException()
    {
        _tracker.GetStockLevel("   ");
    }

    // -------------------------------------------------------------------------
    // AddStock
    // -------------------------------------------------------------------------

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void AddStock_NullSku_ThrowsArgumentNullException()
    {
        _tracker.AddStock(null!, 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_EmptySku_ThrowsArgumentException()
    {
        _tracker.AddStock(string.Empty, 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddStock_WhitespaceSku_ThrowsArgumentException()
    {
        _tracker.AddStock("   ", 10);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddStock_NegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        _tracker.AddStock("SKU-C", -1);
    }

    [TestMethod]
    public void AddStock_ZeroQuantity_StockLevelUnchanged()
    {
        _tracker.AddStock("SKU-D", 100);
        _tracker.AddStock("SKU-D", 0);

        Assert.AreEqual(100, _tracker.GetStockLevel("SKU-D"));
    }

    // -------------------------------------------------------------------------
    // NeedsReorder
    // -------------------------------------------------------------------------

    [TestMethod]
    public void NeedsReorder_BrandNewSku_ReturnsTrue()
    {
        // A SKU with no stock (level = 0) should always trigger a reorder.
        Assert.IsTrue(_tracker.NeedsReorder("SKU-NEW"));
    }

    [TestMethod]
    public void NeedsReorder_AfterAddingLargeStock_ReturnsFalse()
    {
        // 10 000 units is well above any reasonable reorder threshold.
        _tracker.AddStock("SKU-E", 10_000);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-E"));
    }

    [TestMethod]
    public void NeedsReorder_TransitionsFromTrueToFalseAfterRestocking()
    {
        // Verify the flag flips correctly once stock is replenished.
        Assert.IsTrue(_tracker.NeedsReorder("SKU-F"), "Expected reorder needed before restocking.");

        _tracker.AddStock("SKU-F", 10_000);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-F"), "Expected no reorder needed after restocking.");
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentNullException))]
    public void NeedsReorder_NullSku_ThrowsArgumentNullException()
    {
        _tracker.NeedsReorder(null!);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void NeedsReorder_EmptySku_ThrowsArgumentException()
    {
        _tracker.NeedsReorder(string.Empty);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void NeedsReorder_WhitespaceSku_ThrowsArgumentException()
    {
        _tracker.NeedsReorder("   ");
    }

    // -------------------------------------------------------------------------
    // SKU isolation
    // -------------------------------------------------------------------------

    [TestMethod]
    public void AddStock_OneSkuDoesNotAffectAnother()
    {
        _tracker.AddStock("SKU-G", 200);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-H"),
            "Adding stock to SKU-G must not affect SKU-H.");
    }

    [TestMethod]
    public void NeedsReorder_IsEvaluatedIndependentlyPerSku()
    {
        _tracker.AddStock("SKU-I", 10_000); // well-stocked
        // SKU-J is never stocked

        Assert.IsFalse(_tracker.NeedsReorder("SKU-I"), "SKU-I should not need reorder.");
        Assert.IsTrue(_tracker.NeedsReorder("SKU-J"), "SKU-J should need reorder.");
    }
}
