9. export class OrderService {
10.   private readonly orders = new Map<string, Order>();
11. 
12.   create(customer: string, itemCount: number, totalCents: number): Order {
13.     if (!customer) throw new Error('customer is required');
14.     if (itemCount <= 0) throw new Error('itemCount must be positive');
15.     if (totalCents < 0) throw new Error('totalCents must be non-negative');
16.     const order: Order = {
17.       id: `o-${this.orders.size + 1}`,
18.       customer,
19.       itemCount,
20.       totalCents,
21.       status: 'pending',
22.     };
23.     this.orders.set(order.id, order);
24.     return order;
25.   }
26. 
27.   confirm(id: string): Order {
28.     const order = this.orders.get(id);
29.     if (!order) throw new Error('order not found');
30.     order.status = 'confirmed';
31.     return order;
32.   }
33. 
